from collections import deque


def reachable_graph(start, transitions):
    """Return the directed subgraph reachable from start."""
    graph = {}
    pending = deque([start])
    seen = {start}
    while pending:
        state = pending.popleft()
        successors = tuple(transitions.get(state, ()))
        graph[state] = successors
        for nxt in successors:
            if nxt not in seen:
                seen.add(nxt)
                pending.append(nxt)
    return graph


def universal_eventual_arrival(graph, is_goal):
    """Return states from which every maximal execution reaches a goal.

    graph must map every state and successor to its successors. A goal
    counts as reached immediately, even if it has outgoing edges.
    """
    states = set(graph)
    if any(nxt not in states for successors in graph.values()
           for nxt in successors):
        raise ValueError("graph must include every successor")

    winning = {state for state in states if is_goal(state)}
    while True:
        added = {
            state for state in states - winning
            if graph[state] and all(nxt in winning for nxt in graph[state])
        }
        if not added:
            return winning
        winning.update(added)


START = ("A", "B")
A = ("A", "B")
B = ("B", "B")
C = ("C", "B")

# Actual revised machine: the original moves plus B -> C.
REVISED = {A: (B,), B: (A, C), C: ()}

# Hypothetical only: delete B -> A from the revised machine.
VARIANT = {A: (B,), B: (C,), C: ()}


def goal(state):
    return state[0] == "C"


def test_revised_cycle_can_avoid_goal():
    graph = reachable_graph(START, REVISED)
    assert set(graph) == {A, B, C}
    assert universal_eventual_arrival(graph, goal) == {C}


def test_hypothetical_variant_forces_goal():
    graph = reachable_graph(START, VARIANT)
    assert universal_eventual_arrival(graph, goal) == {A, B, C}


def test_non_goal_dead_end_fails():
    graph = {A: (B,), B: ()}
    assert universal_eventual_arrival(graph, goal) == set()


if __name__ == "__main__":
    test_revised_cycle_can_avoid_goal()
    test_hypothetical_variant_forces_goal()
    test_non_goal_dead_end_fails()
```

